// Acceptance checks for WI-001 (R-01, R-02): run greet.js as a user would.
const { test } = require('node:test');
const assert = require('node:assert');
const { spawnSync } = require('node:child_process');
const path = require('node:path');

const script = path.join(__dirname, '..', 'greet.js');

function run(...args) {
  return spawnSync(process.execPath, [script, ...args], { encoding: 'utf8' });
}

const cases = [
  ['R-01: one name', ['Sam'], 'Hello, Sam!\n'],
  ['R-01: several words use the full name', ['Sam', 'Lee'], 'Hello, Sam Lee!\n'],
  ['R-01: spaces inside a quoted name are kept', ['Sam   Lee'], 'Hello, Sam   Lee!\n'],
  ['R-02: no name', [], 'Hello, world!\n'],
  ['R-02: empty name', [''], 'Hello, world!\n'],
  ['R-02: name of only spaces', ['   '], 'Hello, world!\n'],
];

for (const [label, args, expected] of cases) {
  test(label, () => {
    const result = run(...args);
    assert.strictEqual(result.stdout, expected);
    assert.strictEqual(result.stderr, '');
    assert.strictEqual(result.status, 0);
  });
}

